package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Real isolated MySQL, production transaction/mapper/CAS/ledger. Never prepares schema. */
public class B4ControlledWriteTest extends TestCase {
    private A1TestFixture f; private ControlledWriteService service; private long workbook; private ObjectNode request;
    protected void setUp() throws Exception {
        if(!Boolean.getBoolean("a1.schema.prepared"))throw new IllegalStateException("B4 tests require an existing isolated schema");
        f=new A1TestFixture();ObjectNode snapshot=obj().put("id","b4");snapshot.set("sheetOrder",arr().add("s"));
        ObjectNode sheet=obj().put("id","s").put("name","Orders").put("rowCount",20).put("columnCount",10);snapshot.with("sheets").set("s",sheet);
        sheet.with("cellData").with("0").set("0",obj().put("v","outside").put("t",1));ObjectNode row=sheet.with("cellData").with("1");
        ObjectNode zero=obj().put("v",0).put("t",2);zero.set("s",parse("{\"bg\":{\"rgb\":\"#ff0000\"}}"));row.set("1",zero);row.set("2",obj().put("v",false).put("t",3));row.set("3",obj().put("v","").put("t",1));
        ObjectNode rich=obj();rich.set("p",parse("{\"body\":{\"dataStream\":\"rich\\r\\n\"}}"));rich.set("s",obj().put("bl",1));row.set("4",rich);workbook=f.seed(snapshot.toString());
        ObjectNode ws=f.runs.workspace(workbook,1);
        request=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",workbook).put("branchId",ws.path("branchId").asLong()).put("loadedRevision",ws.path("loadedRevision").asText()).put("expectedDraftVersion",-1).put("expectedBranchVersion",ws.path("branchVersion").asLong()).put("activeSheetId","s").put("overwrite","confirmed").put("allowOverwrite",true);
        request.set("writeScopes",parse("[{\"sheetId\":\"s\",\"range\":\"B2:E3\"}]"));
        service=new ControlledWriteService(new AgentStore(f.db),f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());A1TestFixture.inject(service,"enabled",true);A1TestFixture.inject(f.runs,"controlled",service);
    }
    private ObjectNode action(String type,String range){return obj().put("type",type).put("schemaVersion","1.0").put("sheetId","s").put("range",range);}
    private ObjectNode create(ObjectNode a){request.set("actions",arr().add(a));return service.create(request,1);}
    private ObjectNode claim(ObjectNode r){return service.claim(r.path("runId").asText(),1,obj().put("transportVersion",2).put("clientId","b4-test").put("fencingToken",r.path("fencingToken").asLong()));}
    private ObjectNode ack(ObjectNode m){ObjectNode q=obj().put("transportVersion",2).put("callId",m.path("callId").asText()).put("claimToken",m.path("claimToken").asText()).put("argsHash",m.path("argsHash").asText()).put("fencingToken",m.path("fencingToken").asLong()).put("ok",true);ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode actual=obj().put("sheetId",c.path("sheetId").asText()).put("row",c.path("row").asInt()).put("column",c.path("column").asInt()).put("formula","");actual.set("value",c.path("value"));cells.add(actual);}q.set("cells",cells);return q;}
    private ObjectNode save(ObjectNode r,ObjectNode q){return service.receipt(r.path("runId").asText(),1,q);}
    private ObjectNode saved(){return (ObjectNode)parse(String.valueOf(f.status(workbook).get("content")));}
    private long version(){return ((Number)((Map<?,?>)f.status(workbook).get("workingState")).get("version")).longValue();}
    private void reject(Runnable r){try{r.run();fail("Unsafe write accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testAliasRichOverwritePreservesStyleAndOutside(){ObjectNode before=saved(),r=create(action("setCellForCell","E2").put("value",false));ObjectNode out=save(r,ack(claim(r)));assertEquals("COMPLETED",out.path("status").asText());JsonNode cell=saved().path("sheets").path("s").path("cellData").path("1").path("4");assertTrue("Univer boolean storage must retain typed numeric representation",cell.path("v").isIntegralNumber());assertEquals(0,cell.path("v").asInt());assertEquals(3,cell.path("t").asInt());assertFalse(cell.hasNonNull("p"));assertEquals(before.path("sheets").path("s").path("cellData").path("1").path("4").path("s"),cell.path("s"));assertEquals(before.path("sheets").path("s").path("cellData").path("0"),saved().path("sheets").path("s").path("cellData").path("0"));}
    public void testClearTrustedPatchExactReadbackAndIdempotency(){ObjectNode before=saved(),r=create(action("clearRange","B2:E2").put("clearWhat","content"));assertEquals(r.path("runId"),service.create(request,1).path("runId"));ObjectNode m=claim(r),q=ack(m);ObjectNode result=save(r,q).with("lastControlledResult");assertEquals(0,version());assertEquals(4,result.path("executedChange").path("cells").size());assertEquals(before.path("sheets").path("s").path("cellData").path("1").path("1").path("s"),saved().path("sheets").path("s").path("cellData").path("1").path("1").path("s"));ObjectNode args=obj().put("sheetId","s").put("range","B2:E2").put("kind","matches_write");args.set("write",result);assertEquals(4,AgentTools.verify(saved(),args).path("checkedCells").asInt());String content=saved().toString();save(r,q);assertEquals(content,saved().toString());assertEquals(0,version());ObjectNode changed=saved();((ObjectNode)changed.path("sheets").path("s").path("cellData").path("1").path("1")).put("v",false);reject(()->AgentTools.verify(changed,args));ObjectNode forged=args.deepCopy();((ObjectNode)forged.path("write")).put("persistenceStatus","NOT_SAVED");reject(()->AgentTools.verify(saved(),forged));}
    public void testBothNewActionsRejectUnauthorizedUserBeforeCreatingCall(){for(String type:new String[]{"setCellForCell","clearRange"}){ObjectNode a=action(type,"B2");if(type.equals("setCellForCell"))a.put("value",1);request.set("actions",arr().add(a));reject(()->service.create(request,2));}assertNull(f.status(workbook).get("workingState"));assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_run where workbook_id=?",Integer.class,workbook).intValue());}
    public void testMixedUnsafeAndMalformedTargetsCreateNoCall(){ObjectNode good=action("setCellForCell","B2").put("value",1);for(ObjectNode bad:new ObjectNode[]{action("clearRange","C2").put("clearWhat","all"),action("setFormula","C2").put("value","=1"),action("clearRange","B9"),action("setCellForCell","B2").putNull("value"),action("clearRange","B2").put("schemaVersion","2.0")}){request.set("actions",arr().add(good).add(bad));reject(()->service.create(request,1));}assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call c join ai_agent_run r on c.run_id=r.run_id where r.workbook_id=?",Integer.class,workbook).intValue());assertNull(f.status(workbook).get("workingState"));}
    public void testClearWrongReadbackAndSnapshotCannotSave(){ObjectNode r=create(action("clearRange","B2:E2")),q=ack(claim(r));((ObjectNode)q.path("cells").get(0)).put("value","");reject(()->save(r,q));((ObjectNode)q.path("cells").get(0)).putNull("value");q.set("snapshot",obj().put("hacked",true));reject(()->save(r,q));assertNull(f.status(workbook).get("workingState"));}
    public void testAliasFailureUnknownCannotBeClaimedAgain(){ObjectNode r=create(action("setCellForCell","B2").put("value",0)),q=ack(claim(r));q.put("ok",false);q.remove("cells");assertEquals("UNKNOWN",save(r,q).path("call").path("status").asText());reject(()->claim(r));assertNull(f.status(workbook).get("workingState"));}
    public void testClearCasConflictLeavesExternalDraftUntouched(){ObjectNode r=create(action("clearRange","B2:E2")),q=ack(claim(r));f.db.update("insert into ai_workbook_working_state(workbook_id,branch_id,owner_user_id,base_commit_id,draft_actions_json,executed_changes_json,draft_snapshot,content_hash,version,update_time) values(?,?,1,null,'[]','[]',?,?,0,now(3))",workbook,request.path("branchId").asLong(),"{\"external\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8),com.ruoyi.ai.util.ContentHashUtils.sha256("{\"external\":true}"));reject(()->save(r,q));assertEquals("{\"external\":true}",f.status(workbook).get("content"));assertEquals(0,version());}
    public void testCancelledAndExpiredFenceCannotSaveClear(){ObjectNode r=create(action("clearRange","B2:E2")),q=ack(claim(r));f.runs.cancel(r.path("runId").asText(),1);reject(()->save(r,q));f.db.update("update ai_agent_lease set fencing_token=fencing_token+10,expires_at=1 where workbook_id=?",workbook);reject(()->save(r,q));assertNull(f.status(workbook).get("workingState"));}
}
